@Override public void drawLayer(Tile tile){
  try {
    ConveyorEntity entity=tile.entity();
    byte rotation=tile.getRotation();
    for (int i=0; i < entity.convey.size; i++) {
      ItemPos pos=drawpos.set(entity.convey.get(i),ItemPos.drawShorts);
      if (pos.item == null)     continue;
      tr1.trns(rotation * 90,tilesize,0);
      tr2.trns(rotation * 90,-tilesize / 2,pos.x * tilesize / 2);
      Draw.rect(pos.item.region,tile.x * tilesize + tr1.x * pos.y + tr2.x,tile.y * tilesize + tr1.y * pos.y + tr2.y,itemSize,itemSize);
    }
  } catch (NullPointerException e) {
    // Optionally log or ignore
  }
}
